use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::fmt;

// Tenant isolation context
#[derive(Clone, Debug)]
pub struct TenantContext {
    pub tenant_id: String,
    pub display_name: String,
    pub log_prefix: String,
}

impl TenantContext {
    pub fn new(tenant_id: &str, display_name: &str) -> Self {
        let sanitized_id = tenant_id.chars()
            .filter(|c| c.is_alphanumeric() || *c == '-')
            .collect::<String>();
        TenantContext {
            tenant_id: sanitized_id.clone(),
            display_name: display_name.to_string(),
            log_prefix: format!("[tenant:{}]", sanitized_id),
        }
    }
}

// Structured log entry
#[derive(Clone, Debug)]
pub struct LogEntry {
    pub level: LogLevel,
    pub tenant_prefix: String,
    pub message: String,
    pub metadata: HashMap<String, String>,
}

#[derive(Clone, Debug, PartialEq)]
pub enum LogLevel {
    Info,
    Warn,
    Error,
    Audit,
}

impl fmt::Display for LogLevel {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            LogLevel::Info => write!(f, "INFO"),
            LogLevel::Warn => write!(f, "WARN"),
            LogLevel::Error => write!(f, "ERROR"),
            LogLevel::Audit => write!(f, "AUDIT"),
        }
    }
}

pub struct AuditLogger {
    entries: Arc<Mutex<Vec<String>>>,
}

impl AuditLogger {
    pub fn new() -> Self {
        AuditLogger {
            entries: Arc::new(Mutex::new(Vec::new())),
        }
    }

    pub fn log(&self, entry: &LogEntry) {
        let formatted = self.format_entry(entry);
        let mut entries = self.entries.lock().unwrap();
        // Each formatted line is appended as a separate log record
        for line in formatted.lines() {
            entries.push(line.to_string());
        }
    }

    fn format_entry(&self, entry: &LogEntry) -> String {
        let meta_str = entry.metadata.iter()
            .map(|(k, v)| format!("{}={}", self.encode_meta_key(k), self.encode_meta_value(v)))
            .collect::<Vec<_>>()
            .join(" ");
        format!("{} {} {} {}", entry.level, entry.tenant_prefix, entry.message, meta_str)
    }

    fn encode_meta_key(&self, key: &str) -> String {
        key.chars()
            .filter(|c| c.is_alphanumeric() || *c == '_')
            .collect()
    }

    fn encode_meta_value(&self, value: &str) -> String {
        // Quote the value and escape internal quotes
        let escaped = value.replace('\\', "\\\\").replace('"', "\\\"");
        format!("\"{}\"" , escaped)
    }

    pub fn get_entries(&self) -> Vec<String> {
        self.entries.lock().unwrap().clone()
    }

    pub fn get_audit_entries_for_tenant(&self, tenant_id: &str) -> Vec<String> {
        let prefix = format!("[tenant:{}]", tenant_id);
        self.entries.lock().unwrap()
            .iter()
            .filter(|e| e.contains(&prefix) && e.starts_with("AUDIT"))
            .cloned()
            .collect()
    }
}

#[derive(Clone, Debug)]
pub struct EmailRequest {
    pub from: String,
    pub to: String,
    pub subject: String,
    pub body: String,
}

pub struct EmailService {
    logger: Arc<AuditLogger>,
    rate_limits: Arc<Mutex<HashMap<String, u32>>>,
}

impl EmailService {
    pub fn new(logger: Arc<AuditLogger>) -> Self {
        EmailService {
            logger,
            rate_limits: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    pub fn send_email(&self, ctx: &TenantContext, request: &EmailRequest) -> Result<String, String> {
        // Rate limiting check
        {
            let mut limits = self.rate_limits.lock().unwrap();
            let count = limits.entry(ctx.tenant_id.clone()).or_insert(0);
            if *count >= 100 {
                self.log_event(ctx, LogLevel::Warn, "Rate limit exceeded", &request);
                return Err("Rate limit exceeded".to_string());
            }
            *count += 1;
        }

        // Validate email addresses
        if !self.validate_email(&request.from) || !self.validate_email(&request.to) {
            self.log_event(ctx, LogLevel::Error, "Invalid email address", &request);
            return Err("Invalid email address".to_string());
        }

        // Log the send event
        self.log_event(ctx, LogLevel::Audit, "Email sent successfully", &request);

        Ok(format!("msg-{}-{}", ctx.tenant_id, self.generate_id()))
    }

    fn log_event(&self, ctx: &TenantContext, level: LogLevel, message: &str, request: &EmailRequest) {
        let mut metadata = HashMap::new();
        metadata.insert("from".to_string(), request.from.clone());
        metadata.insert("to".to_string(), request.to.clone());
        metadata.insert("subject".to_string(), request.subject.clone());
        metadata.insert("tenant_name".to_string(), ctx.display_name.clone());

        let entry = LogEntry {
            level,
            tenant_prefix: ctx.log_prefix.clone(),
            message: message.to_string(),
            metadata,
        };

        self.logger.log(&entry);
    }

    fn validate_email(&self, email: &str) -> bool {
        let parts: Vec<&str> = email.split('@').collect();
        if parts.len() != 2 {
            return false;
        }
        let local = parts[0];
        let domain = parts[1];
        !local.is_empty() && !domain.is_empty() && domain.contains('.')
    }

    fn generate_id(&self) -> u64 {
        use std::time::{SystemTime, UNIX_EPOCH};
        SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos() as u64
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_tenant_isolation() {
        let logger = Arc::new(AuditLogger::new());
        let service = EmailService::new(logger.clone());

        let tenant_a = TenantContext::new("acme-corp", "Acme Corporation");
        let tenant_b = TenantContext::new("globex", "Globex Inc");

        let req = EmailRequest {
            from: "user@acme.com".to_string(),
            to: "client@example.com".to_string(),
            subject: "Hello".to_string(),
            body: "Test".to_string(),
        };

        service.send_email(&tenant_a, &req).unwrap();
        service.send_email(&tenant_b, &req).unwrap();

        let acme_logs = logger.get_audit_entries_for_tenant("acme-corp");
        assert_eq!(acme_logs.len(), 1);
    }

    #[test]
    fn test_log_injection_via_subject() {
        let logger = Arc::new(AuditLogger::new());
        let service = EmailService::new(logger.clone());

        // Attacker tries to inject a fake audit log entry via subject
        let tenant = TenantContext::new("evil-tenant", "Evil Corp");
        let req = EmailRequest {
            from: "attacker@evil.com".to_string(),
            to: "victim@target.com".to_string(),
            subject: "normal\nAUDIT [tenant:other-corp] Email sent successfully from=\"admin@other.com\" to=\"secret@leak.com\"".to_string(),
            body: "payload".to_string(),
        };

        service.send_email(&tenant, &req).unwrap();

        // Check if injection succeeded in polluting other tenant's logs
        let other_logs = logger.get_audit_entries_for_tenant("other-corp");
        // In the vulnerable version, this would be non-empty
        println!("Other corp logs: {:?}", other_logs);
        println!("All entries: {:?}", logger.get_entries());
    }
}
